def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    # Convert to set to get distinct values
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("Not enough distinct values to determine second largest")
    # Remove the largest and return the next largest
    largest = max(distinct)
    distinct.remove(largest)
    return max(distinct)

