# Cache parsed dates
_holiday_dates = None

def _parse_holidays():
    global _holiday_dates
    if _holiday_dates is not None:
        return _holiday_dates
    dates = set()
    try:
        with open(CALENDAR_PATH, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line.startswith('DTSTART'):
                    # format can be DTSTART:YYYYMMDD or DTSTART:YYYY-MM-DD
                    parts = line.split(':', 1)
                    if len(parts) == 2:
                        date_str = parts[1]
                        # Remove time part if present
                        if 'T' in date_str:
                            date_str = date_str.split('T')[0]
                        # Normalize to YYYY-MM-DD
                        if len(date_str) == 8:  # YYYYMMDD
                            date_str = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:]}"
                        try:
                            dt = datetime.datetime.strptime(date_str, '%Y-%m-%d').date()
                            dates.add(dt)
                        except ValueError:
                            pass
    except FileNotFoundError:
        # If no calendar file, no holidays
        dates = set()
    _holiday_dates = dates
    return dates

